module dram_cell (
    input wire clk,
    input wire reset,
    input wire WE,
    input wire RE,
    input wire [3:0] data_in,
    output reg [3:0] data_out
);
    reg [3:0] memory;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            memory <= 4'b0000;
            data_out <= 4'b0000;
        end else if (WE) begin
            memory <= data_in;
        end else if (RE) begin
            data_out <= memory;
        end
    end
endmodule

