module tcp_segmenter #(
    parameter DATA_WIDTH = 32,
    parameter SEGMENT_SIZE = 8
) (
    input [DATA_WIDTH-1:0] data_in,
    input valid_in,
    output reg [SEGMENT_SIZE-1:0] segment_out,
    output reg valid_out
);
    integer i;

    always @(*) begin
        valid_out = 0;
