module dvfs_controller(
    input wire clk,
    input wire [1:0] voltage_level,
    output reg dvfs_clk
);
    reg [31:0] counter;

    always @(posedge clk) begin
        counter <= counter + 1;
        case (voltage_level)
            2'b00: begin // Low voltage, low frequency
                if (counter[23:0] == 24'hFFFFFF) // Adjust this for low frequency
                    dvfs_clk <= ~dvfs_clk;
            end
            2'b01: begin // Medium voltage, medium frequency
                if (counter[21:0] == 22'h3FFFFF) // Adjust this for medium frequency
                    dvfs_clk <= ~dvfs_clk;
            end
            2'b10: begin // High voltage, high frequency
                if (counter[19:0] == 20'hFFFFF) // Adjust this for high frequency
                    dvfs_clk <= ~dvfs_clk;
            end
            default: dvfs_clk <= dvfs_clk;
        endcase
    end
endmodule

