module crc16_generator (
    input clk,
    input rst_n,
    input start,
    input [15:0] data_in,
    input [15:0] crc_init,
    output reg [15:0] crc_out,
    output reg done
);
    reg [15:0] crc;
    reg [4:0] bit_count;
    reg processing;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            crc <= crc_init;
            bit_count <= 0;
            done <= 0;
            processing <= 0;
        end else if (start && !processing) begin
            crc <= crc_init;
            bit_count <= 15;
            done <= 0;
            processing <= 1;
        end else if (processing) begin
            if (bit_count >= 0) begin
                crc <= (crc << 1) ^ ((crc[15] ^ data_in[bit_count]) ? 16'hA001 : 16'h0000);
                bit_count <= bit_count - 1;
            end else begin
                crc_out <= crc;
                done <= 1;
                processing <= 0;
            end
        end
    end
endmodule

