module deadbeat_controller(clk, reset, input_signal, control_signal);  
    input clk;  
    input reset;  
    input [3:0] input_signal;  
    output reg [1:0] control_signal;  

    reg [1:0] state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 2'b00;  
            control_signal <= 2'b00;  
        end else begin  
            case (state)  
                2'b00: begin  
                    if (input_signal != 4'b0000) begin  
                        control_signal <= 2'b01;  
                        state <= 2'b01;  
                    end  
                end  
                2'b01: begin  
                    control_signal <= 2'b10;  
                    state <= 2'b10;  
                end  
                2'b10: begin  
                    control_signal <= 2'b00;  
                    state <= 2'b00;  
                end  
                default: state <= 2'b00;  
            endcase  
        end  
    end  
endmodule

