module pll_2x (  
    input wire clk_in,  
    input wire enable,  
    output reg clk_out,  
    output reg locked  
);  
    reg [1:0] clk_div;  

    always @(posedge clk_in or negedge enable) begin  
        if (!enable) begin  
            clk_div <= 0;  
            clk_out <= 0;  
            locked <= 0;  
        end else begin  
            clk_div <= clk_div + 1;  
            if (clk_div == 2) begin  
                clk_out <= ~clk_out;  
                clk_div <= 0;  
            end  
            locked <= 1;  
        end  
    end  
endmodule

