module spi_controller (  
    input wire clk,  
    input wire cs,  
    input wire mode,  
    input wire [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg ready  
);  

    reg [2:0] bit_index;  
    reg [7:0] shift_reg;  

    always @(posedge clk or negedge cs) begin  
        if (!cs) begin  
            bit_index <= 3'b000;  
            ready <= 1'b0;  
            shift_reg <= 8'b00000000;  
        end else begin  
            if (mode) begin // Send mode  
                if (bit_index < 3'b111) begin  
                    shift_reg <= {data_in[7], shift_reg[7:1]};  
                    bit_index <= bit_index + 1;  
                end else begin  
                    data_out <= shift_reg;  
                    ready <= 1'b1;  
                end  
            end else begin // Receive mode  
                if (bit_index < 3'b111) begin  
                    shift_reg <= {shift_reg[6:0], 1'b0};  
                    bit_index <= bit_index + 1;  
                end else begin  
                    data_out <= shift_reg;  
                    ready <= 1'b1;  
                end  
            end  
        end  
    end  
endmodule

