module butterworth_filter (
    input clk,
    input reset,
    input signed [15:0] x_in,  // Input signal
    output reg signed [15:0] y_out // Filtered output signal
);

    reg signed [15:0] x1, x2; // Delayed inputs
    reg signed [15:0] y1, y2; // Delayed outputs

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x1 <= 0;
            x2 <= 0;
            y1 <= 0;
            y2 <= 0;
            y_out <= 0;
        end else begin
            // 2nd-order Butterworth filter coefficients (example values)
            x2 <= x1; 
            x1 <= x_in;
            y_out <= (x1 + x2) - (y1 + y2);
            y2 <= y1;
            y1 <= y_out;
        end
    end
endmodule

