module kalman_filter (
    input clk,
    input rst,
    input [15:0] z1, // first measurement
    input [15:0] z2, // second measurement
    output reg [15:0] x, // estimated state
    output reg [15:0] P  // error covariance
);
    reg [15:0] Q = 16'h0001; // Process noise covariance
    reg [15:0] R = 16'h0004; // Measurement noise covariance
    reg [15:0] K; // Kalman Gain

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x <= 16'h0000;
            P <= 16'h0001;
        end else begin
            // Prediction step
            P <= P + Q;

            // Measurement update step for z1
            K <= P / (P + R);
            x <= x + K * (z1 - x);
            P <= (1 - K) * P;

            // Measurement update step for z2
            K <= P / (P + R);
            x <= x + K * (z2 - x);
            P <= (1 - K) * P;
        end
    end
endmodule

module crc_generator (
    input wire clk,
    input wire reset,
    input wire data_in,
    output reg [15:0] crc_out
);
    reg [15:0] crc; // CRC register

    // Polynomial: x^16 + x^12 + x^5 + 1 (0xA001)
    wire feedback;

    // Feedback is the last bit of the CRC
    assign feedback = crc[15] ^ data_in;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            crc <= 16'hFFFF; // Initialize CRC to all ones
        end else begin
            crc <= {crc[14:0], 1'b0} ^ (feedback ? 16'hA001 : 16'h0000);
        end
    end

    always @(posedge clk) begin
        crc_out <= crc;
    end
endmodule

