module linked_list_traversal (
    input clk,
    input reset,
    input [7:0] current_data,
    input move_next,
    output reg [7:0] current_node,
    output reg done
);
    reg [7:0] list [0:4]; // Sample linked list of 5 nodes
    integer index;

    initial begin
        list[0] = 8'h01; // Data for node 1
        list[1] = 8'h02; // Data for node 2
        list[2] = 8'h03; // Data for node 3
        list[3] = 8'h04; // Data for node 4
        list[4] = 8'hFF; // End of list marker
        index = 0;
        done = 0;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            index <= 0;
            done <= 0;
            current_node <= list[0];
        end else if (move_next) begin
            if (list[index] == 8'hFF) begin
                done <= 1;
            end else begin
                index <= index + 1;
                current_node <= list[index];
            end
        end
    end
endmodule

module qr_decomposition (
    input clk,
    input [15:0] a11, a12, a21, a22, // Input matrix elements
    output reg [15:0] q11, q12, q21, q22, // Orthogonal matrix Q
    output reg [15:0] r11, r12, r21, r22 // Upper triangular matrix R
);

reg [15:0] norm_a1, norm_a2, proj_a2_on_a1;
reg [15:0] a1_q11, a1_q12, a2_r21, a2_r22;

always @(posedge clk) begin
    // Step 1: Calculate norm of the first vector
    norm_a1 <= a11 * a11 + a21 * a21; // Square of norm
    q11 <= a11 / (norm_a1 ** 0.5);
    q21 <= a21 / (norm_a1 ** 0.5);

    // Step 2: Project the second vector onto the first
    proj_a2_on_a1 <= (a12 * q11 + a22 * q21);
    r11 <= norm_a1 ** 0.5;
    r12 <= proj_a2_on_a1;

    // Step 3: Calculate the orthogonal component of the second vector
    a1_q12 <= a12 - proj_a2_on_a1 * q12; // Note: q12 is calculated similarly to q11
    q12 <= a1_q12 / (a1_q12 * a1_q12 ** 0.5);

    // Step 4: Fill R matrix
    r21 <= a21 * q12;
    r22 <= a22 * q22;
end
endmodule

