module fp_multiplier (
    input [31:0] A,
    input [31:0] B,
    output reg [31:0] C
);
    wire sign_a = A[31];
    wire sign_b = B[31];
    wire sign_c = sign_a ^ sign_b; // Calculate sign of the product

    wire [7:0] exp_a = A[30:23];
    wire [7:0] exp_b = B[30:23];
    wire [23:0] mant_a = {1'b1, A[22:0]}; // Implicit leading 1
    wire [23:0] mant_b = {1'b1, B[22:0]};

    wire [7:0] exp_sum = exp_a + exp_b - 8'd127; // Adjust for bias
    wire [47:0] mant_product = mant_a * mant_b; // 24 * 24 -> 48 bits

    always @(*) begin
        if (mant_product[47]) begin
            // Normalization
            C = {sign_c, exp_sum + 8'd1, mant_product[46:24]}; // Shift right
        end else begin
            // No normalization needed
            C = {sign_c, exp_sum, mant_product[45:23]};
        end
    end
endmodule

module mpc_controller(  
    input clk,  
    input reset,  
    input [7:0] current_state,  
    input [7:0] setpoint,  
    output reg [7:0] control_signal  
);  
    reg [7:0] error;  
    parameter Kp = 8'd5;  // Proportional gain  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            control_signal <= 8'd0;  
        end else begin  
            error <= setpoint - current_state;  
            control_signal <= control_signal + (Kp * error);  
        end  
    end  
endmodule

