module rrt_explorer(  
    input wire clk,  
    input wire reset,  
    input wire start_exploration,  
    input wire [4:0] random_point,  
    output reg [4:0] current_point,  
    output reg found_target  
);  

    reg [4:0] target_point;  
    reg [3:0] state;  

    parameter IDLE = 4'b0000,  
              EXPLORING = 4'b0001,  
              FOUND = 4'b0010;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            current_point <= 5'b00000;  
            found_target <= 1'b0;  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start_exploration) begin  
                        target_point <= 5'b11111; // Example target  
                        state <= EXPLORING;  
                    end  
                end  
                EXPLORING: begin  
                    current_point <= random_point;  
                    if (current_point == target_point) begin  
                        found_target <= 1'b1;  
                        state <= FOUND;  
                    end  
                end  
                FOUND: begin  
                    // Stay in FOUND state  
                end  
            endcase  
        end  
    end  
endmodule

module lfsr_8bit(
    input clk,
    input rst,
    input [7:0] seed,
    output reg [7:0] out
);
    reg [7:0] lfsr;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            lfsr <= seed;
        end else begin
            // Feedback polynomial: x^8 + x^6 + x^5 + x^4 + 1
            lfsr <= {lfsr[6:0], lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[6]};
        end
    end

    always @(posedge clk) begin
        out <= lfsr;
    end
endmodule

module sliding_window_protocol #(parameter N = 4) (
    input clk,
    input rst,
    input send_packet,
    input ack,
    output reg [N-1:0] sent_packets,
    output reg [N-1:0] ack_packets
);
    reg [N-1:0] window;
    reg [2:0] state; // 0: idle, 1: sending, 2: waiting for ack

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 0;
            sent_packets <= 0;
            ack_packets <= 0;
            window <= 0;
        end else begin
            case (state)
                0: begin // idle state
                    if (send_packet && (sent_packets < N)) begin
                        window <= (1 << sent_packets);
                        sent_packets <= sent_packets + 1;
                        state <= 1;
                    end
                end
                1: begin // sending state
                    state <= 2; // move to waiting for ack
                end
                2: begin // waiting for ack
                    if (ack) begin
                        ack_packets <= ack_packets | window;
                        window <= 0;
                        state <= 0; // return to idle
                    end
                end
            endcase
        end
    end
endmodule

