module divide_by_8(input clk, input rst_n, input [7:0] data_in, output reg [7:0] data_out);  
    reg [2:0] counter;  
    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            data_out <= 8'b0;  
            counter <= 3'b0;  
        end else begin  
            if (counter == 3'b111) begin  
                data_out <= data_in;  
            end  
            counter <= counter + 1;  
        end  
    end  
endmodule

