module option_pricing (
    input [7:0] S, // Current stock price
    input [7:0] K, // Strike price
    input [3:0] T, // Time to expiration in years
    input [3:0] r, // Risk-free interest rate (in percentage scaled by 100)
    output reg [9:0] C // Option price
);

    wire [15:0] K_discounted; // K discounted by e^(-rT)
    wire [9:0] profit; // Profit calculation

    // Calculate K * e^(-rT) (simplified for small r and T)
    assign K_discounted = K * (16'hFFFF >> (r * T)); // Simple approximation for e^(-rT)

    // Calculate profit
    assign profit = (S > K_discounted) ? (S - K_discounted[7:0]) : 10'd0;

    always @(*) begin
        C = profit;
    end
endmodule

