module crc_generator (
    input wire clk,
    input wire rst,
    input wire [15:0] data_in,
    output reg [15:0] crc_out,
    output reg valid
);
    reg [15:0] crc;
    reg [3:0] count;
    parameter POLYNOMIAL = 16'hA001; // Example polynomial

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc <= 16'hFFFF; // Initial CRC value
            count <= 0;
            crc_out <= 0;
            valid <= 0;
        end else begin
            if (count < 16) begin
                crc[15:1] <= crc[14:0]; // Shift left
                crc[0] <= data_in[count]; // Input data bit
                if (crc[15]) begin
                    crc <= crc ^ POLYNOMIAL; // Apply polynomial
                end
                count <= count + 1;
            end else begin
                crc_out <= crc;
                valid <= 1;
            end
        end
    end
endmodule

